<?php require_once 'includes/functions.php';$u=login_required('patient');$id=(int)($_GET['id']??$_POST['id']??0);$s=db()->prepare("SELECT r.*,d.name donor_name FROM blood_requests r JOIN users d ON d.user_id=r.donor_id WHERE r.request_id=? AND r.patient_id=? AND r.status='Confirmed'");$s->execute([$id,$u['user_id']]);$r=$s->fetch();if(!$r)exit('Only confirmed donations can be reviewed.');$err='';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$rating=(int)($_POST['rating']??0);$comment=trim($_POST['comment']??'');if($rating<1||$rating>5)$err='Choose a rating from 1 to 5.';else try{db()->prepare('INSERT INTO reviews(request_id,patient_id,donor_id,rating,comment) VALUES(?,?,?,?,?)')->execute([$id,$u['user_id'],$r['donor_id'],$rating,$comment]);notice((int)$r['donor_id'],'You received a review for request #'.$id,'review');flash('Thank you for your review.');go('dashboard.php');}catch(Throwable $e){$err='A review may already exist for this donation.';}}$title='Review';require 'includes/header.php';?><section class="form"><h1>Rate and review</h1><p>Donor: <?=e($r['donor_name'])?></p><?php if($err):?><p class="alert error"><?=e($err)?></p><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="id" value="<?=$id?>"><label>Rating<select name="rating"><?php for($i=5;$i>=1;$i--):?><option value="<?=$i?>"><?=$i?> / 5</option><?php endfor;?></select></label><label>Comment<textarea name="comment" maxlength="1000"></textarea></label><button class="btn">Submit review</button></form></section><?php require 'includes/footer.php';?>